  `tittle_effect` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `atac_not` int(11) NOT NULL DEFAULT '0',
  `critic` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '3',
  `chans_dop` int(11) NOT NULL DEFAULT '0',
  `chans_effect` int(11) NOT NULL DEFAULT '0',
  `cool_attak` int(11) NOT NULL DEFAULT '0',
  `cool_attak2` int(11) NOT NULL DEFAULT '0',
  `dop_effect` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `priorety` int(11) NOT NULL DEFAULT '0',
  `stati` int(11) NOT NULL DEFAULT '0',
  `attac_effecti` int(11) NOT NULL DEFAULT '0',
  `titles` text COLLATE utf8mb4_unicode_ci NOT NULL,
  UNIQUE KEY `atac_id` (`atac_id`),
  KEY `atac_categori` (`atac_categori`),
  KEY `atac_pp` (`atac_pp`),
  KEY `atac_power` (`atac_power`),
