DROP TABLE IF EXISTS `battles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `battles` (
  `id` int(11) NOT NULL,
  `user_1` int(11) NOT NULL,
  `user_2` int(11) NOT NULL,
  `poke_1` char(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `poke_2` char(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attac_1` int(11) NOT NULL,
  `attac_2` int(11) NOT NULL,
  `item_1` int(11) NOT NULL,
  `item_2` int(11) NOT NULL,
  `to_p` char(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `to_p2` char(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `batl_tip` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `time` int(11) NOT NULL,
  `pobeda` int(11) NOT NULL DEFAULT '0',
  `raund` int(11) NOT NULL DEFAULT '1',
  `effect_go` int(11) NOT NULL DEFAULT '0',
  `effect_go2` int(11) NOT NULL DEFAULT '0',
  `effect` int(11) NOT NULL DEFAULT '0',
  `effect2` int(11) NOT NULL DEFAULT '0',
  `id_pogodi` int(11) NOT NULL DEFAULT '1',
  `times` int(11) NOT NULL DEFAULT '0',
  `time_1` int(11) NOT NULL DEFAULT '0',
  `time_2` int(11) NOT NULL DEFAULT '0',
  `to_it` int(11) NOT NULL DEFAULT '0',
  `to_it2` int(11) NOT NULL DEFAULT '0',
  `hod_user_id` int(11) NOT NULL DEFAULT '0',
  `tips_battle` int(11) NOT NULL DEFAULT '0',
  `zamtru_1` int(11) NOT NULL DEFAULT '0',
  `zamtru_2` int(11) NOT NULL DEFAULT '0',
  `room` int(11) NOT NULL DEFAULT '0',
  `dates` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

