),(78,0,'Случайная TM-атака','Случайная техническая машина с атакой для обучения покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(217,0,'Витамины PP','Редкие витамины, используемые для восстановления или усиления PP.',0,1,0,1,1,0,1,'0',0,'market_item'),(234,0,'Черная флейта','Флейта с темным звуком для игровых эффектов и событий.',0,1,0,1,1,0,1,'0',0,'market_item'),(235,0,'Белая флейта','Флейта со светлым звуком для игровых эффектов и событий.',0,1,0,1,1,0,1,'0',0,'market_item'),(325,0,'Лист разума','Редкий лист, связанный с тренировкой разума покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(371,0,'Увеличитель линзы','Предмет, повышающий точность и внимательность в бою.',0,1,0,1,1,0,1,'0',0,'market_item'),(651,0,'Красная конфета','Редкая конфета красного цвета для развития покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(652,0,'Розовая конфета','Редкая конфета розового цвета для развития покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(653,0,'Шоколадная конфета','Редкая шоколадная конфета для развития покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(654,0,'Серая конфета','Редкая серая конфета для развития покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(655,0,'Необычная конфета','Необычная конфета с особым игровым эффектом.',0,1,0,1,1,0,1,'0',0,'market_item'),(861,0,'Кекс с ягодами Церуго','Кекс с ягодами Церуго для восстановления сил.',0,1,0,1,1,0,1,'0',0,'market_item'),(1401,0,'Золотая конфета','Очень редкая золотая конфета для ценного усиления покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(90004,0,'Мастербол','Редкий шар с максимальным шансом ловли дикого покемона.',0,1,0,1,1,0,1,'0',0,'market_item'),(90005,0,'Премиум бол','Улучшенный покебол с повышенным шансом ловли.',0,1,0,1,1,0,1,'0',0,'premium');
