CREATE TABLE `pok_user` (
  `id` int(11) NOT NULL,
  `users` int(11) NOT NULL,
  `basenum` int(11) NOT NULL,
  `names` char(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `active` int(11) NOT NULL DEFAULT '0',
  `evcount` int(11) NOT NULL DEFAULT '0',
  `lvl` int(11) NOT NULL DEFAULT '1',
  `sex` int(11) NOT NULL DEFAULT '1',
  `har` int(11) NOT NULL DEFAULT '1',
  `hp_my` int(11) NOT NULL,
  `hp_max` int(11) NOT NULL,
  `exp` int(11) NOT NULL,
  `exp_b` int(11) NOT NULL,
  `atk` int(11) NOT NULL,
  `def` int(11) NOT NULL,
  `satk` int(11) NOT NULL,
  `sdef` int(11) NOT NULL,
  `speed` int(11) NOT NULL,
