  `def_ev` int(11) NOT NULL,
  `satk_ev` int(11) NOT NULL,
  `sdef_ev` int(11) NOT NULL,
  `speed_ev` int(11) NOT NULL,
  `hp_iv` int(11) NOT NULL,
  `atk_iv` int(11) NOT NULL,
  `def_iv` int(11) NOT NULL,
  `satk_iv` int(11) NOT NULL,
  `sdef_iv` int(11) NOT NULL,
  `speed_iv` int(11) NOT NULL,
  `tips` char(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `startone` int(11) NOT NULL DEFAULT '0',
  `startepoke` int(11) NOT NULL DEFAULT '0',
