  `datemay` datetime NOT NULL,
  `usersone` int(11) NOT NULL,
  `sprz` int(11) NOT NULL DEFAULT '0',
  `item` int(11) NOT NULL,
  `ability_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `training_stage` tinyint(4) NOT NULL DEFAULT '0',
  `training_stat` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `training_named_effect` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `training_tamed` tinyint(4) NOT NULL DEFAULT '0',
  `training_updated_at` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
