DROP TABLE IF EXISTS `quest_process`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quest_process` (
  `id` int(11) NOT NULL,
  `q_id` int(11) NOT NULL,
