/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `login` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none@mail.ru',
  `online` int(11) NOT NULL DEFAULT '0',
  `onlinetime` int(11) unsigned NOT NULL,
  `activation` int(11) NOT NULL DEFAULT '1',
  `groups` int(11) NOT NULL,
  `moderation` int(11) NOT NULL DEFAULT '0',
  `police` int(11) NOT NULL DEFAULT '0',
  `datereg` datetime NOT NULL,
  `avatars` int(11) unsigned NOT NULL DEFAULT '1',
  `clanid` int(11) NOT NULL DEFAULT '0',
  `clan_point` float NOT NULL DEFAULT '0',
  `clan_adm` int(11) NOT NULL DEFAULT '0',
  `pve` int(11) NOT NULL DEFAULT '0',
  `pvp` int(11) NOT NULL DEFAULT '0',
  `trade` bigint(20) NOT NULL,
  `info` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` int(11) NOT NULL DEFAULT '1',
  `ip` int(10) unsigned NOT NULL,
  `rang` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `rang_a` int(11) NOT NULL DEFAULT '0',
  `rang_b` int(11) NOT NULL DEFAULT '0',
  `rang_c` int(11) NOT NULL DEFAULT '0',
  `karma_score` int(11) NOT NULL DEFAULT '0',
  `count_poke` int(15) NOT NULL DEFAULT '0',
  `count_poke_s` int(15) NOT NULL DEFAULT '0',
  `buildmy` int(11) NOT NULL DEFAULT '1',
  `mychat` int(11) NOT NULL DEFAULT '1',
  `newuser` int(11) NOT NULL,
  `battleid` int(11) NOT NULL DEFAULT '0',
  `pve_button` int(11) NOT NULL DEFAULT '0',
  `atack_poke` int(11) NOT NULL DEFAULT '0',
  `status_klan` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `youtuber` tinyint(3) NOT NULL DEFAULT '0',
  `prefics` int(11) NOT NULL,
  `timepoke` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_users_login` (`login`)
) ENGINE=InnoDB AUTO_INCREMENT=10145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

